<script setup lang="ts">
import { computed,onMounted,onUnmounted,ref } from 'vue'
import { NAlert,NButton,NEmpty,NModal,NSpin,NTag } from 'naive-ui'
import { api,stamp } from '../api'
import { diagnosticSummary,probePending } from '../featureState'
import type { DiagnosticJob } from '../featureState'
const props=defineProps<{node:{id:number;name:string}}>(),emit=defineEmits<{close:[]}>()
const job=ref<DiagnosticJob|null>(null),busy=ref(false),error=ref('')
const summary=computed(()=>diagnosticSummary(job.value)),details=computed(()=>job.value?.diagnostics)
let timer:ReturnType<typeof setTimeout>|undefined,active=true,version=0
const states:Record<string,string>={queued:'等待领取',running:'诊断中',succeeded:'诊断已返回',failed:'诊断失败',unsupported:'不支持诊断',expired:'任务过期'}
const runtimeLabels:Record<string,string>={running:'运行中',stopped:'已停止',idle:'空闲',starting:'启动中',failed:'启动失败',exited:'已退出',unassigned:'未分配运行实例',unsupported:'不支持',unknown:'未知'}
async function poll(id:string,run:number){
 try{const data=await api<DiagnosticJob>(`/api/admin/probes/${encodeURIComponent(id)}`);if(!active||version!==run)return;error.value='';job.value=data;if(probePending(data))timer=setTimeout(()=>poll(id,run),1800)}catch(e){if(active&&version===run)error.value='读取诊断结果失败：'+(e as Error).message}
}
async function start(){
 if(busy.value||probePending(job.value))return
 const run=++version;clearTimeout(timer);busy.value=true;error.value='';job.value=null
 try{const data=await api<DiagnosticJob>(`/api/admin/nodes/${props.node.id}/diagnostics`,{method:'POST',body:'{}'});if(!active||version!==run)return;job.value=data;if(probePending(data)&&data.id)timer=setTimeout(()=>poll(data.id!,run),1500)}catch(e){if(active&&version===run)error.value=(e as Error).message}finally{if(active&&version===run)busy.value=false}
}
onMounted(start)
onUnmounted(()=>{active=false;version++;clearTimeout(timer)})
</script>
<template><n-modal :show="true" preset="card" class="resource-modal diagnostics-modal" :title="'故障查询 · '+node.name" :bordered="false" @update:show="value=>{if(!value)emit('close')}"><p class="muted small">由归属节点机检查监听、内核运行及用户下发，并返回脱敏诊断和日志摘要。不会远程执行任意命令或重启服务。</p><n-alert :type="summary.tone" :title="summary.title" class="space-bottom">{{summary.detail}}</n-alert><n-alert v-if="error" type="error" class="space-bottom">{{error}}<n-button v-if="job?.id" size="small" @click="poll(job.id!,version)">重试读取结果</n-button></n-alert><n-spin :show="busy"><div v-if="job" class="diagnostic-meta"><n-tag :bordered="false" size="small">{{states[job.state]||job.state}}</n-tag><span>来源：{{job.source||'归属节点机'}}</span><span>创建 {{stamp(job.created_at)}}</span><span v-if="job.finished_at">完成 {{stamp(job.finished_at)}}</span><span v-if="job.error_code">错误阶段：{{job.error_code}}</span></div><template v-if="details"><section class="diagnostic-grid"><div><span>配置端口 / 传输</span><strong>{{details.expected_port||'未指定'}} / {{details.transport||'未知'}}</strong></div><div><span>监听状态</span><strong>{{details.listening===true?'已监听':details.listening===false?'未监听':'未确认'}}</strong></div><div><span>符合使用条件的用户</span><strong>{{details.eligible_users??'未知'}}</strong></div><div><span>运行状态</span><strong>{{runtimeLabels[details.runtime_state]||details.runtime_state||'未知'}}</strong></div></section><h2>节点机发现</h2><div v-for="(finding,index) in details.findings||[]" :key="index" class="finding"><n-tag size="small" :bordered="false" :type="finding.severity==='error'?'error':finding.severity==='warning'?'warning':'info'">{{finding.severity==='error'?'错误':finding.severity==='warning'?'提醒':'信息'}}</n-tag><div><strong>{{finding.message}}</strong><small>{{finding.code}}</small></div></div><n-empty v-if="!details.findings?.length" size="small" description="未返回额外发现"/><h2 class="logs-title">脱敏日志摘要</h2><pre v-if="details.logs?.length" class="diagnostic-logs">{{details.logs.map(log=>`[机器范围 · ${log.code}] ${log.message} · ${log.count} 次`).join('\n')}}</pre><p v-else class="muted small">本次未返回日志摘要。</p><p class="table-note">日志仅为机器范围的固定分类摘要，不能证明某条日志属于当前节点。节点机不会返回原始 journal 文本、私钥、完整代理配置或远端响应。只对当前管理员显示。</p></template><p v-else-if="!busy" class="muted small">节点机未返回诊断资料时，面板无法代替 SSH 读取远程日志。请检查服务器在线状态、原生版本和机器认证。</p></n-spin><template #footer><div class="modal-footer"><n-button @click="emit('close')">关闭</n-button><n-button type="primary" :loading="busy||probePending(job)" :disabled="probePending(job)" @click="start">重新查询</n-button></div></template></n-modal></template>
<style scoped>.resource-modal.diagnostics-modal{width:min(760px,calc(100vw - 30px))!important}.diagnostic-meta{display:flex;gap:10px 16px;flex-wrap:wrap;align-items:center;color:var(--muted);font-size:11px;margin:15px 0 23px}.diagnostic-grid{display:grid;grid-template-columns:1fr 1fr;gap:20px;padding:18px 0 25px;border-top:1px solid var(--line)}.diagnostic-grid>div{display:grid;gap:7px}.diagnostic-grid span,.finding small{font-size:11px;color:var(--muted)}.diagnostic-grid strong{font-size:14px;overflow-wrap:anywhere}.finding{display:flex;gap:12px;border-top:1px solid var(--line);padding:14px 0}.finding>div{min-width:0;display:grid;gap:7px}.finding strong{font-size:12px;line-height:1.8;overflow-wrap:anywhere}.logs-title{margin-top:22px}.diagnostic-logs{white-space:pre-wrap;overflow-wrap:anywhere;background:var(--canvas);border:1px solid var(--line);border-radius:9px;padding:15px;font:12px/1.8 Consolas,monospace;max-height:260px;overflow:auto}@media(max-width:550px){.diagnostic-grid{gap:18px 10px}.diagnostic-meta{gap:8px}.finding{gap:8px}}</style>
